                    c.r[22] = mmi::psrah::<7>(c.r[22]);
                    // 0x7e4 sdl $s2, 0x13($v1)
                    if !sdx(&fm, (c.r[3] as u32).wrapping_add(0x13), c.r[18] as u64, true) {
                        return deopt(c, fr, fr.pc(0x7e4), _t + 26);
                    }
                    // 0x7e8 ppacb $s6, $s6, $s7
                    c.r[22] = mmi::ppacb(c.r[22], c.r[23]);
