                    c.r[15] = mmi::pextlb(0u128, c.r[28]);
                    // 0x814 qmfc2 $s4, vf12
                    c.r[20] = V::ld(c.vf[12]).to_u128();
                    // 0x818 pextub $gp, $zero, $gp
                    c.r[28] = mmi::pextub(0u128, c.r[28]);
