    pub mod region {
    // Region 23 of skinned_vertex_stream (0x1e80c0), 0x1e91b0..0x1e925c. SPEED STYLE (S2g inline MMIO): GPRs in locals, every memory access is ONE ld*!/st*! line
    // (Fm fast path for RAM/scratchpad, else the recompiled slow path; the DMA channel stores 0x1000d4xx run inline, no deopt).
    // RELOCATABLE: every pc is fr.pc(OFF); no level-dependent immediate (the only lui is 0x1001, the gp-free DMA offsets are literal).
    use super::gen::*;
    use crate::cpu::Cpu;
    use crate::hs::{deopt, due_within, Frame};
    use crate::hs_fast::{lo, sx32, wlo, Fm};
    
    pub fn region(c: &mut Cpu, fr: &Frame) -> bool {
        let b0: usize = match c.pc.wrapping_sub(fr.base) {
            0x10f0 => 0,
            _ => return false,
        };
        run(c, fr, b0)
    }
    
    #[inline(always)]
    fn run(c: &mut Cpu, fr: &Frame, mut b: usize) -> bool {
        let mut ic = c.icount;
        let fm = Fm::new(c);
        // Entry values (low 64 bits) of the GPRs the region reads or writes.
        let mut s0 = lo(c, 16);
        let mut s1 = lo(c, 17);
        let mut fp = lo(c, 30);
        let t8 = lo(c, 24);
        let mut at = lo(c, 1);
        let mut v0 = lo(c, 2);
        let mut v1 = lo(c, 3);
        let mut a0 = lo(c, 4);
        let mut a1 = lo(c, 5);
        let mut a2 = lo(c, 6);
        let mut a3 = lo(c, 7);
        let mut t6 = lo(c, 14);
        let mut t7 = lo(c, 15);
        let mut t9 = lo(c, 25);
        // Write back EVERY GPR the region modified (idempotent; used before every exit, deopt and inline MMIO access).
        macro_rules! flush {
            () => {{
                c.icount = ic;
                wlo(c, 1, at);
                wlo(c, 2, v0);
                wlo(c, 3, v1);
                wlo(c, 4, a0);
                wlo(c, 5, a1);
                wlo(c, 6, a2);
                wlo(c, 7, a3);
                wlo(c, 14, t6);
                wlo(c, 15, t7);
                wlo(c, 16, s0);
                wlo(c, 17, s1);
                wlo(c, 25, t9);
                wlo(c, 30, fp);
            }};
        }
        loop {
            match b {
                // block 0 @0x1e91b0: 2 insns (beqz $s1 ; slot xori $s0), br: e0 taken -> EXIT 0x1e9430, e1 fall -> b1
                0 => {
                    if due_within(c, 2) {
                        flush!();
                        return deopt(c, fr, fr.pc(0x10f0), c.icount);
                    }
                    ic += T[0] as u64;
                    let taken = s1 == 0; // beqz $s1: condition read before the slot
                    s0 ^= 0x800; // xori $s0, $s0, 0x800 (delay slot)
                    if taken {
                        let _ = go!(c, fr, 0);
                        return true;
                    }
                    b = go!(c, fr, 1);
                    continue;
                }
                // block 1 @0x1e91b8: 7 insns (loop header, due window 41), br: e2 taken -> b1, e3 fall -> b2
                1 => {
                    c.icount = ic;
                    if due_within(c, 41) {
                        flush!();
                        return deopt(c, fr, fr.pc(0x10f8), c.icount);
                    }
                    let ib = ic;
                    // lw $t7, 4($fp) is the DELAY SLOT of beqz $a0 (0x110c): ld32! there would deopt at pc+4 (the fall-through pc), wrong when the
                    // branch is taken. Read it first in guard form: a Fm refusal deopts at the block start (no effect of this block done yet).
                    let t7r = match fm.r32((fp as u32).wrapping_add(4)) {
                        Some(v) => v,
                        None => {
                            flush!();
                            return deopt(c, fr, fr.pc(0x10f8), ib);
                        }
                    };
                    ic += T[1] as u64;
                    a0 = ld64!(c, fr, fm, s1 as u32, 4, fr.pc(0x10f8), ib + 1, 40); // ld $a0, ($s1)
                    t9 = sx32(0x1001_0000); // lui $t9, 0x1001
                    at = sx32(ld32!(c, fr, fm, (fp as u32).wrapping_add(8), 1, fr.pc(0x1100), ib + 3, 38)); // lw $at, 8($fp)
                    v1 = s0 ^ 0x800; // xori $v1, $s0, 0x800
                    // nop
                    let taken = a0 == 0; // beqz $a0: condition read before the slot
                    t7 = sx32(t7r); // lw $t7, 4($fp) (delay slot of beqz $a0; read above)
                    if taken {
                        b = go!(c, fr, 2);
                        continue;
                    }
                    b = go!(c, fr, 3);
                    continue;
                }
                // block 2 @0x1e91d4: 2 insns (beqz $at ; slot addi $s1, $zero, 0), br: e4 taken -> b4, e5 fall -> b3
                2 => {
                    ic += T[2] as u64;
                    let taken = at == 0; // beqz $at: condition read before the slot
                    s1 = 0; // addi $s1, $zero, 0 (delay slot)
                    if taken {
                        b = go!(c, fr, 4);
                        continue;
                    }
                    b = go!(c, fr, 5);
                    continue;
                }
                // block 3 @0x1e91dc: 14 insns, fall: e6 -> b4. Elapsed from the b1 header = 9 + k (REM = 32 - k)
                3 => {
                    let ib = ic;
                    ic += T[3] as u64;
                    v0 = at & 0xff; // andi $v0, $at, 0xff
                    at = sx32((at as u32) >> 8); // srl $at, $at, 8
                    st32!(c, fr, fm, (t9 as u32).wrapping_sub(0x2b80), v1 as u32, fr.pc(0x1124), ib + 3, 29); // sw $v1, -0x2b80($t9)
                    at = sx32((at as u32) << 4); // sll $at, $at, 4
                    st32!(c, fr, fm, (t9 as u32).wrapping_sub(0x2be0), v0 as u32, fr.pc(0x112c), ib + 5, 27); // sw $v0, -0x2be0($t9)
                    v0 = sx32((v0 as u32) << 4); // sll $v0, $v0, 4
                    st32!(c, fr, fm, (t9 as u32).wrapping_sub(0x2bf0), at as u32, fr.pc(0x1134), ib + 7, 25); // sw $at, -0x2bf0($t9)
                    s1 = sx32((v1 as u32).wrapping_add(v0 as u32)); // add $s1, $v1, $v0
                    s1 = sx32((s1 as u32).wrapping_sub(0x10)); // addi $s1, $s1, -0x10
                    st64!(c, fr, fm, s1 as u32, 0u64, fr.pc(0x1144), ib + 11, 21); // sd $zero, ($s1)
                    at = 0x100; // addi $at, $zero, 0x100
                    st32!(c, fr, fm, (t9 as u32).wrapping_sub(0x2c00), at as u32, fr.pc(0x114c), ib + 13, 19); // sw $at, -0x2c00($t9)
                    b = go!(c, fr, 6);
                    continue;
                }
                // block 4 @0x1e9214: 18 insns, fall: e7 -> EXIT 0x1e925c. REM = 18 - k
                4 => {
                    let ib = ic;
                    ic += T[4] as u64;
                    at = sx32((s0 as u32).wrapping_add(0x10)); // addi $at, $s0, 0x10
                    t9 = sx32(ld32!(c, fr, fm, s0 as u32, 25, fr.pc(0x1158), ib + 2, 16)); // lw $t9, ($s0)
                    v1 = sx32((t8 as u32).wrapping_add(0x3000)); // addi $v1, $t8, 0x3000
                    a0 = sx32(ld32!(c, fr, fm, (s0 as u32).wrapping_add(4), 4, fr.pc(0x1160), ib + 4, 14)); // lw $a0, 4($s0)
                    a1 = sx32(ld32!(c, fr, fm, (s0 as u32).wrapping_add(8), 5, fr.pc(0x1164), ib + 5, 13)); // lw $a1, 8($s0)
                    a3 = sx32((t9 as u32) << 4); // sll $a3, $t9, 4
                    t6 = sx32(ld32!(c, fr, fm, (s0 as u32).wrapping_add(0xc), 14, fr.pc(0x116c), ib + 7, 11)); // lw $t6, 0xc($s0)
                    a3 = sx32((a3 as u32).wrapping_add(at as u32)); // add $a3, $a3, $at
                    a0 = sx32((a0 as u32).wrapping_add(v1 as u32)); // add $a0, $a0, $v1
                    a1 = sx32((a1 as u32).wrapping_add(v1 as u32)); // add $a1, $a1, $v1
                    a2 = sx32((t6 as u32).wrapping_add(v1 as u32)); // add $a2, $t6, $v1
                    st128!(c, fr, fm, (a0 as u32).wrapping_sub(0x10), 0u128, fr.pc(0x1180), ib + 12, 6); // sq $zero, -0x10($a0)
                    st128!(c, fr, fm, (a1 as u32).wrapping_sub(0x10), 0u128, fr.pc(0x1184), ib + 13, 5); // sq $zero, -0x10($a1)
                    t6 = sx32((t6 as u32) >> 4); // srl $t6, $t6, 4
                    st128!(c, fr, fm, (a2 as u32).wrapping_sub(0x10), 0u128, fr.pc(0x118c), ib + 15, 3); // sq $zero, -0x10($a2)
                    v0 = u64::MAX; // addi $v0, $zero, -1
                    st128!(c, fr, fm, a3 as u32, 0u128, fr.pc(0x1194), ib + 17, 1); // sq $zero, 0x0($a3)
                    fp = sx32((fp as u32).wrapping_add(8)); // addi $fp, $fp, 8
                    let _ = go!(c, fr, 7);
                    return true;
                }
                _ => unreachable!(),
            }
        }
    }
    }
