    /// Declared deopt stub (S2g): the block's Rust is NOT written; the block start deopts (`flush!()` first). Use it as the first statement of a block arm that the
    /// gate cannot run to its end in Rust (the gate refuses a block with a Rust body that never completed; a stub is the honest form). `ic` = the instruction
    /// count at the block start (plain style `_t`, speed style the local before `ic += T[i]`).
    macro_rules! stub {
        ($c:expr, $fr:expr, $b:expr, $ic:expr) => {{
            flush!();
            crate::hs::stub_hit($b);
            return crate::hs::deopt($c, $fr, $fr.pc(super::gen::BLOCK_PC[$b]), $ic);
        }};
    }
    
    /// INLINE MMIO (S2g): a load/store that `Fm` rejects (hardware register, DMA, VU mirror ...) runs through the recompiled code's own slow path
