    macro_rules! ld8 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r8, u8, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld16 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r16, u16, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld32 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r32, u32, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld64 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r64, u64, $a, $dst, $pc, $ic, $rem) }; }
